return [
    ['no' => 1, 'level' => '上上', 'title' => '钟离成道', 'verse' => ['天开地辟结良缘', '日吉时良万事全', '若得此签非小可', '人行中正帝王宣'], 'gist' => '开天辟地，诸事大吉', 'interpretation' => '此签为上上之象。事业正当开创之时，谋事顺遂、名利可期；姻缘天作之合，婚恋皆成；财运亨通，求财可得；身体康健。凡事秉持中正之心，自有贵人提携、声名显达。'],
    ['no' => 2, 'level' => '中平', 'title' => '苏秦不第', 'verse' => ['鲸鱼未化守江湖', '未许升腾离碧波', '异日峥嵘身变化', '从教一跃禹门过'], 'gist' => '时运未到，蓄势待发', 'interpretation' => '此签为鲸鱼未化之象。事业眼下困守原地，急进无功，宜沉潜积累；姻缘暂缓，强求不遂；财运平平，守成为宜；健康无碍但忌操劳。他时运至，自有一跃成龙之日，耐心等待即可。'],
