    ['no' => 4, 'level' => '上吉', 'title' => '玉莲会十朋', 'verse' => ['菱花镜破复重圆', '女再求夫男再婚', '自此门闾重改换', '更添福禄与儿孙'], 'gist' => '破镜重圆，失而复得', 'interpretation' => '此签为破镜重圆之象。事业经一番波折后重上正轨，旧业复兴更胜从前；姻缘主复合重圆，离异再婚亦吉；财运失而复得，渐入佳境；健康旧疾可愈。凡事虽经离散，终得团圆美满。'],
    ['no' => 5, 'level' => '中吉', 'title' => '刘晨遇仙', 'verse' => ['一锄掘地要求泉', '努力求之得最先', '无意俄然遇知己', '相逢携手上青天'], 'gist' => '努力营求，偶遇知己', 'interpretation' => '此签为掘地求泉之象。事业需脚踏实地勤勉经营，贵人将于无意间出现相助；姻缘不求而遇，缘分自来；财运辛勤可得，横财运弱；健康平稳。凡事刻意难求、随缘反成，努力之后自有相逢携手之喜。'],
    ['no' => 6, 'level' => '中吉', 'title' => '仁贵遇主', 'verse' => ['投身岩下饲于菟', '须是还他大丈夫', '舍己也应难再得', '通行天下此人无'], 'gist' => '舍己利人，得遇明主', 'interpretation' => '此签为舍身饲虎之象。事业上有担当、肯付出者终遇赏识之人，先舍后得；姻缘须以真心换真心，宜大度包容；财运不可锱铢必较，大舍大得；健康无虞。凡事存大义、行厚道，方能通行天下。'],
    ['no' => 7, 'level' => '中平', 'title' => '苏娘走难', 'verse' => ['奔波役役重重险', '带水拖泥又渡山', '更虑他方求别用', '千山万水未能还'], 'gist' => '奔波险阻，守旧为宜', 'interpretation' => '此签为带水泥渡山之象。事业多阻隔艰辛，远行调动不利，守成为上；姻缘聚少离多，异地难成；财运劳碌少得，不宜外求；健康防跋涉劳损。凡事退一步则稳，进一步则难，安守现状待时运转。'],
    ['no' => 8, 'level' => '上上', 'title' => '裴度还带', 'verse' => ['岁寒松柏古栽培', '雨雪风霜总不摧', '异日必当成大用', '功名作个栋梁材'], 'gist' => '松柏长青，终成大器', 'interpretation' => '此签为岁寒松柏之象。事业根基深厚，经得起风雨考验，日后必成栋梁；姻缘坚贞长久，可托终身；财运稳中有升，厚积大发；健康如松柏之寿。凡事守正不阿、多积阴德，名利自然水到渠成。'],
    ['no' => 9, 'level' => '中平', 'title' => '孔明点将', 'verse' => ['劳君问我心中事', '此意偏宜说向公', '一片灵台明似镜', '恰如明月正当空'], 'gist' => '心地光明，坦白无私', 'interpretation' => '此签为明月当空之象。事业宜公开透明、以诚待人，暗中谋划反而不利；姻缘坦诚则成，隐瞒则败；财运正财可得，偏财莫贪；健康心境安宁则身安。凡事只要问心无愧、襟怀坦白，自然逢凶化吉、诸事顺遂。'],
    ['no' => 10, 'level' => '中平', 'title' => '庞涓观阵', 'verse' => ['椟藏无价宝和珍', '只管他乡外处寻', '好似将灯来觅火', '不如安静莫劳心'], 'gist' => '珍宝在己，莫向外求', 'interpretation' => '此签为将灯觅火之象。事业所求的资源机会其实近在身旁，勿舍近求远、盲目跳槽转行；姻缘良人或在身边，留心旧识；财运守成有得，外求徒劳；健康宜静养。凡事反求诸己，安静守住本分即是得。'],
    ['no' => 11, 'level' => '上上', 'title' => '书荐姜维', 'verse' => ['欲求好事喜非常', '争奈姻亲只暂忙', '毕竟到头成好事', '贵人接引贵人乡'], 'gist' => '好事多磨，贵人接引', 'interpretation' => '此签为贵人接引之象。事业虽暂有阻滞，终得贵人荐举提携而成；姻缘好事多磨，波折之后终成眷属；财运先难后易，渐入佳境；健康小恙无碍。凡事不必急于求成，守得云开，自有接引之人。'],
    ['no' => 12, 'level' => '上上', 'title' => '武吉遇师', 'verse' => ['时临否极泰当来', '抖擞从君出暗埃', '若遇卯寅佳信至', '管教立志事和谐'], 'gist' => '否极泰来，佳音将至', 'interpretation' => '此签为否极泰来之象。事业困顿已尽，转运在即，立春前后多有佳音；姻缘低迷将过，新春萌生良缘；财运由滞转通；健康沉疴渐愈。凡事宜抖擞精神、立志向前，时运一到，万事和谐顺遂。'],
    ['no' => 13, 'level' => '中吉', 'title' => '罗通拜帅', 'verse' => ['自小生身富贵家', '眼前万事总奢华', '要君赐受金鱼袋', '四海传名足可夸'], 'gist' => '少年得志，名扬四海', 'interpretation' => '此签为少年拜帅之象。事业得遇赏识，年少亦可担重任，名声渐起；姻缘门户相当，成就佳偶；财运丰厚，宜大方经营；健康精力正旺。唯须戒骄戒躁，富贵中不忘修身，方能长久。'],
    ['no' => 14, 'level' => '中吉', 'title' => '子牙弃官', 'verse' => ['宛如仙鹤出樊笼', '脱却羁縻处处通', '南北东西无障碍', '任君直上九霄中'], 'gist' => '脱却羁绊，路路皆通', 'interpretation' => '此签为仙鹤出笼之象。事业摆脱束缚之后天地顿宽，跳槽、自立皆可行；姻缘脱离旧纠葛，新缘自在；财运四方通泰，动中求财；健康郁结得舒。凡事放下牵绊、勇往直前，自此无往不利。'],
    ['no' => 15, 'level' => '中平', 'title' => '苏秦得志', 'verse' => ['触人口气最难吞', '忽有灾危祸到门', '卵破巢空无宿处', '深为稳便把心存'], 'gist' => '忍气守稳，谨防灾祸', 'interpretation' => '此签为鸟鹊离林之象。事业防口舌是非与突发变故，切忌与人争执硬碰；姻缘多口角，宜忍气吞声；财运守成为上，防破耗；健康注意意外伤害。凡事退一步海阔天空，把稳心神、守旧待时即可避祸。'],
    ['no' => 16, 'level' => '中吉', 'title' => '叶梦熊朝帝', 'verse' => ['攒眉思虑暂时开', '咫尺云开见日来', '宛如污泥中片玉', '良工一举出尘埃'], 'gist' => '云开见日，脱颖而出', 'interpretation' => '此签为污泥藏玉之象。事业怀才不遇只是暂时，将有识才之人举荐而出；姻缘真心终被看见；财运困中将通；健康愁闷得解。凡事不必妄自菲薄，养精蓄锐，良工一至，自可出尘埃而见天日。'],
    ['no' => 17, 'level' => '中平', 'title' => '望梅止渴', 'verse' => ['莫听闲言与是非', '晨昏只好念阿弥', '若将妄语为真实', '画饼如何疗得饥'], 'gist' => '莫信虚言，务实为上', 'interpretation' => '此签为画饼充饥之象。事业莫信空头许诺与谗言是非，落实书面凭据方稳妥；姻缘勿听旁人挑拨，耳听为虚；财运防空头支票与骗局；健康心安则身安。凡事求真务实，虚妄之辞不可当真。'],
    ['no' => 18, 'level' => '上上', 'title' => '曹国舅为仙', 'verse' => ['金乌西坠兔东升', '日夜循环至古今', '僧道得之无不利', '士农工商各从心'], 'gist' => '顺应天时，各遂其愿', 'interpretation' => '此签为日月循环之象。事业顺应时势、按部就班则万事亨通，三百六十行皆有所成；姻缘天定，顺其自然自成；财运时来运转，正财旺盛；健康作息规律则安。凡事不违天时、不逆自然，随心所愿皆可成就。'],
    ['no' => 19, 'level' => '中平', 'title' => '子仪封王', 'verse' => ['急水滩头放艇时', '狂风作浪欲何为', '待他浪静风停后', '稳载船归过不危'], 'gist' => '风浪正急，静待时机', 'interpretation' => '此签为船行急滩之象。事业当前风高浪急，切勿轻举妄动，待局势平稳再出手；姻缘风波未息，缓议为宜；财运忌冒险投资；健康防急火攻心。凡事沉住气，风浪过后自能安稳渡岸、满载而归。'],
