    ['no' => 21, 'level' => '上吉', 'title' => '李旦龙凤配合', 'verse' => ['阴阳道合总由天', '女嫁男婚岂偶然', '但看龙蛇堪运动', '熊罴叶梦喜团圆'], 'gist' => '姻缘天定，龙凤呈祥', 'interpretation' => '此签为阴阳和合之象。姻缘上上，婚嫁天作之合，求嗣有喜；事业得阴阳相辅、贵人配合，谋事可成；财运和合生财；健康阴阳调和则安。凡事皆由天定，顺势而为，龙蛇之年月多有喜庆团圆。'],
    ['no' => 22, 'level' => '中吉', 'title' => '六郎逢救', 'verse' => ['四郊田亩皆枯竭', '久旱俄然三日霖', '花果草芽俱润泽', '始知一雨值千金'], 'gist' => '久旱逢霖，困中得助', 'interpretation' => '此签为久旱逢雨之象。事业困顿之际忽得援手，绝处逢生；姻缘枯木逢春，旧情复燃或新缘忽至；财运周转不灵时得意外资助；健康久恙得遇良医。凡事危急之时自有甘霖，心怀感恩、知恩图报。'],
    ['no' => 23, 'level' => '中平', 'title' => '怀德招亲', 'verse' => ['欲攀仙桂蟾宫去', '岂虑天门不放开', '谋望一般音信好', '高人自送岭头来'], 'gist' => '谋望虽高，终有回音', 'interpretation' => '此签为蟾宫折桂之象。事业目标虽高，却有高人引路，音信可期；姻缘须借媒妁贵人撮合；财运缓图可得；健康无大碍。凡事志向可存，但须量力而行、借力而为，切勿自恃过高、孤军深入。'],
    ['no' => 24, 'level' => '下下', 'title' => '殷郊遇师', 'verse' => ['不成邻里不成家', '水泡痴人似落花', '若问君恩难得力', '到头毕竟事如麻'], 'gist' => '所谋落空，诸事缠杂', 'interpretation' => '此签为水中泡花之象。事业根基不稳、所托非人，计划多成泡影；姻缘虚花不实，恐遇负心；财运虚多实少，谨防受骗；健康心绪烦乱宜静养。凡事此时不宜大兴大动，收拾纷乱、回归根本方是出路。'],
    ['no' => 25, 'level' => '中吉', 'title' => '李广机智', 'verse' => ['过了忧危第几重', '从今再历永无凶', '宽心自有宽心计', '得遇高人护圣功'], 'gist' => '忧危已过，高人相护', 'interpretation' => '此签为过尽险关之象。事业重重危机已然度过，此后渐入坦途，并有高人护持；姻缘误会凶险皆成过往；财运转危为安；健康大病得愈。凡事放宽心怀、自有计较，昔日艰危皆成垫脚之石。'],
    ['no' => 26, 'level' => '中平', 'title' => '钟馗得道', 'verse' => ['上下传来事总虚', '天边接得一封书', '书中许我功名事', '直待终时亦是无'], 'gist' => '虚名无实，勿信空言', 'interpretation' => '此签为虚名一纸之象。事业防口头承诺与空头委任，一切落实为凭；姻缘花言巧语不可信；财运防合同文书之诈；健康勿信偏方传言。凡事所闻多虚、所望多幻，脚踏实地、眼见为实方不受骗。'],
    ['no' => 27, 'level' => '中吉', 'title' => '刘基谏主', 'verse' => ['一谋一用一番机', '虑后疑前不敢为', '时至自然逢贵助', '银墙铁壁好安居'], 'gist' => '谋定后动，贵人相助', 'interpretation' => '此签为深谋安居之象。事业宜深思熟虑、谋定后动，时机一到自有贵人助力；姻缘多虑反误，顺其自然；财运稳健置业为宜；健康安守则安。凡事前怕狼后怕虎不如静待时机，根基固后方享安稳。'],
    ['no' => 28, 'level' => '中吉', 'title' => '李后寻包公', 'verse' => ['东方月上正婵娟', '顷刻云遮月半边', '莫道圆时还又缺', '须教缺处复重圆'], 'gist' => '月缺复圆，先损后得', 'interpretation' => '此签为云遮复圆之象。事业中途有波折遮蔽，坚持之后重归圆满；姻缘或有一段分离冷落，终得复合团圆；财运先损后益；健康小恙可愈。凡事不因一时缺损而灰心，缺处重圆只在迟早之间。'],
    ['no' => 29, 'level' => '中吉', 'title' => '赵子龙救阿斗', 'verse' => ['宝剑光芒出匣时', '匣中应不被尘欺', '贵人亲手提携起', '尽可防身更无疑'], 'gist' => '宝剑出匣，贵人提携', 'interpretation' => '此签为宝剑出匣之象。事业才华得遇识主，贵人亲手提拔，自此锋芒得展；姻缘得良人护卫依靠；财运因贵得财；健康有惊无险。凡事积蓄已久正当其用，乘势而为，可保进退有据、声名渐显。'],
    ['no' => 30, 'level' => '中平', 'title' => '棋盘大会', 'verse' => ['劝君切莫向他求', '似鹤飞来暗箭投', '若去采薪蛇伏草', '恐遭毒手也堪忧'], 'gist' => '外求有险，谨防暗算', 'interpretation' => '此签为暗藏杀机之象。事业忌轻信他人、贸然求助于人，防笑里藏刀之辈；姻缘所托须查其真心；财运防暗亏与骗局；健康防意外伤毒。凡事向内求安稳，向外多陷阱，守己防人可保安然。'],
    ['no' => 31, 'level' => '中平', 'title' => '佛印会东坡', 'verse' => ['清闲无事静处坐', '饥时吃饭困时卧', '放下身心不用忙', '必定不遭殃与祸'], 'gist' => '清闲自守，平安是福', 'interpretation' => '此签为静处安身之象。事业不宜多动多争，守住本分、按部就班自无祸殃；姻缘随缘而不强求；财运够用即是福，勿起贪念；健康静养调息最宜。凡事饥餐困眠、身心放下，平淡之中自有真味。'],
    ['no' => 32, 'level' => '中平', 'title' => '刘备求贤', 'verse' => ['渺渺前途事可疑', '石中藏玉有谁知', '一朝良匠分明剖', '始觉其中碧玉奇'], 'gist' => '石中藏玉，待匠而剖', 'interpretation' => '此签为剖石得玉之象。事业前途看似渺茫，实则身怀大才，只待识货之人；姻缘真心有待慧眼识之；财运暗财可掘，需借行家指点；健康隐患宜早查。凡事不必自疑，良匠一至，自见碧玉之奇。'],
    ['no' => 33, 'level' => '中吉', 'title' => '咬金聘仁贵', 'verse' => ['石藏美玉在中心', '得指何须向外寻', '直待高人来剖析', '恰如灵雨涤烦襟'], 'gist' => '美玉在怀，高人指路', 'interpretation' => '此签为石中藏玉之象。事业身怀至宝而不自知，得高人点拨即豁然开通，无须舍近求远；姻缘良配或在咫尺；财运内藏可发；健康烦郁得舒。凡事向内发掘、虚心受教，一经剖析，如灵雨涤心。'],
    ['no' => 34, 'level' => '中吉', 'title' => '桃园结义', 'verse' => ['出入行藏礼义恭', '言必忠良听必聪', '心下了然俱洞彻', '光明如日正当空'], 'gist' => '忠信笃敬，光明显达', 'interpretation' => '此签为红日当空之象。事业以礼义立身、与同道同心协力，则无往不利；姻缘以诚信相交，情比金坚；财运合伙同心则生财；健康心胸坦荡则身健。凡事心存忠良、言信行恭，自得心明眼亮、事事洞彻。'],
    ['no' => 35, 'level' => '中吉', 'title' => '唐僧取经', 'verse' => ['衣冠重整旧家风', '道是无功却有功', '扫却当途荆棘碍', '三人约议再和同'], 'gist' => '重整旗鼓，同心成事', 'interpretation' => '此签为衣冠重整之象。事业先难后易，整顿旧业、扫除障碍后可再兴；姻缘重修旧好或重整家风皆吉；财运与人合伙同心则利；健康调治得法渐安。凡事看似无功实则有功，三人同心、其利断金。'],
    ['no' => 36, 'level' => '中吉', 'title' => '湘子遇宾', 'verse' => ['目前病讼不须忧', '实地资财尽可求', '恰好系猿今脱锁', '得归仙洞去来游'], 'gist' => '脱锁归山，自在无忧', 'interpretation' => '此签为猿猴脱锁之象。事业眼前病讼烦忧皆可化解，自此摆脱束缚、自在施展；姻缘脱离纠缠、得获自由身；财运实地经营可得；健康病厄得解。凡事受困只是一时，枷锁一脱，去来自如、逍遥可期。'],
    ['no' => 37, 'level' => '中平', 'title' => '李靖归山', 'verse' => ['欲待身安运泰时', '风中灯烛不相宜', '不如收拾深堂坐', '庶免光摇静处明'], 'gist' => '风烛飘摇，静守为安', 'interpretation' => '此签为风中灯烛之象。事业时运未稳，宜退守内室、收敛锋芒，妄动则光彩飘摇；姻缘静处则安；财运守成为上；健康注意保养元气、勿过劳。凡事此时不争不显，深堂稳坐，静处方得光明。'],
    ['no' => 38, 'level' => '中平', 'title' => '何文秀遇难', 'verse' => ['镜月当空出匣时', '刹那云雾暗迷离', '宽心守待浮云散', '更改相宜可望为'], 'gist' => '云雾遮月，守待云散', 'interpretation' => '此签为云雾遮月之象。事业本有光明前景，忽遭一时遮蔽阻滞，宽心守待即可；姻缘暂有误会隔阂，云散自明；财运迟滞，待时而通；健康小病缠绵终会愈。凡事不必改弦更张，浮云散尽依旧青天。'],
    ['no' => 39, 'level' => '下下', 'title' => '姜女寻夫', 'verse' => ['天边消息应难问', '切莫私心强望求', '若把石头磨作镜', '精神枉费一时休'], 'gist' => '磨石作镜，枉费心力', 'interpretation' => '此签为磨石作镜之象。事业所求遥远难及，执着强求只是枉费精神，宜及早转念；姻缘千里难寻、强求无益；财运劳而无获；健康勿忧思过度。凡事明知不可为而为之，不如收心改途，另寻切实之路。'],
    ['no' => 40, 'level' => '中平', 'title' => '武则天登位', 'verse' => ['红轮西坠兔东升', '阴长阳消是两形', '若是女人占此卦', '增添福禄称心情'], 'gist' => '阴长阳消，女占尤吉', 'interpretation' => '此签为日月交替之象。事业主阴阳转换、格局翻新，女性问事尤为得利；姻缘女强男顺则和美；财运女命求之更顺；健康阴阳宜调。凡事顺时而变、各得其位，女性添福增禄，男性则宜退居辅位。'],
    ['no' => 41, 'level' => '中平', 'title' => '董卓收吕布', 'verse' => ['无限好事君须记', '恰如认贼作为子', '莫贪眼下有些甜', '可虑他时还受苦'], 'gist' => '眼前之甜，他日之苦', 'interpretation' => '此签为认贼作子之象。事业防甜头背后的圈套，合作用人须察其底细；姻缘勿被一时殷勤迷惑；财运贪小便宜必吃大亏；健康防甜腻伤身。凡事记取教训、慎思明辨，眼下甘言小利，正是他日苦楚之媒。'],
    ['no' => 42, 'level' => '上上', 'title' => '目莲救母', 'verse' => ['君皇圣后总为恩', '复待祈禳无损增', '一切有情皆受用', '人间天上得期亨'], 'gist' => '天恩普降，万物沾泽', 'interpretation' => '此签为天垂恩泽之象。事业上得上峰眷顾提携，谋事大吉、无有偏私；姻缘上天作合，孝义感动而成；财运普沾恩利；健康祈保得安。凡事心怀慈孝、广结善缘，人间天上皆得亨通。'],
    ['no' => 43, 'level' => '上上', 'title' => '行者得道', 'verse' => ['天地交泰万物新', '自形自色自怡神', '森罗万象皆精彩', '事事和谐得称心'], 'gist' => '天地交泰，万事称心', 'interpretation' => '此签为天地交泰之象。事业焕然一新、左右逢源，所谋皆成；姻缘和谐美满，两情相悦；财运通达顺遂；健康身心怡然。凡事顺应自然、不必强求，万象更新之际，事事和谐、无往不利。'],
    ['no' => 44, 'level' => '中吉', 'title' => '姜维邓艾斗阵', 'verse' => ['棋逢对手要藏机', '黑白盘中未决时', '到底欲知谁胜负', '须教先着相机宜'], 'gist' => '棋逢对手，先着为胜', 'interpretation' => '此签为棋逢敌手之象。事业竞争激烈，胜负未分，须藏机蓄势、抢占先机；姻缘两厢对峙，宜以智取不以力强；财运相机而动可获利；健康防神经紧张。凡事观机应变、谋定后动，先着一子者胜。'],
    ['no' => 45, 'level' => '上吉', 'title' => '仁宗认母', 'verse' => ['温柔自古胜刚强', '积善之门大吉昌', '若是有人占此卦', '宛如正渴遇琼浆'], 'gist' => '温柔积善，如渴遇浆', 'interpretation' => '此签为甘露解渴之象。事业以柔克刚、以善待人，则贵人和合、所求皆遂；姻缘温柔者得佳偶；财运积善之家必有余财；健康心境柔和则病退。凡事切忌强硬争胜，温良积德，如久渴忽遇琼浆。'],
    ['no' => 46, 'level' => '中吉', 'title' => '渭水钓鱼', 'verse' => ['劝君耐守旧生涯', '把定身心莫听邪', '直待有人轻着力', '满园枯木再开花'], 'gist' => '耐守旧业，枯木逢春', 'interpretation' => '此签为枯木再花之象。事业守住本业勿听邪说动摇，时机一至、贵人轻扶即重焕生机；姻缘守旧待缘，正缘未至莫急；财运守成则有，妄动则失；健康静养回春。凡事把定身心，枯木逢春只在早晚。'],
    ['no' => 47, 'level' => '上上', 'title' => '梁灏登科', 'verse' => ['锦上添花色更鲜', '运来禄马喜双全', '时人莫讶功名晚', '一举登科四海传'], 'gist' => '锦上添花，大器晚成', 'interpretation' => '此签为锦上添花之象。事业运至禄马双全，功名虽晚终成，一举成名天下知；姻缘晚婚反得美满；财运后福丰厚；健康老而弥健。凡事莫嫌时晚、莫恨迟来，厚积薄发，迟开之花分外鲜妍。'],
    ['no' => 48, 'level' => '中吉', 'title' => '韩信挂帅', 'verse' => ['鹍鸟秋光化作鹏', '翱翔得意尽飞腾', '直冲万里云霄外', '任是诸禽总不能'], 'gist' => '化鹏展翅，一飞冲天', 'interpretation' => '此签为鹍鸟化鹏之象。事业经一番蜕变后扶摇直上，才智远胜同侪，宜放手高飞；姻缘登第之后良缘自至；财运宏图大展；健康精神焕发。凡事时机已备，只管振翅直冲云霄，众禽难以望其项背。'],
    ['no' => 49, 'level' => '中平', 'title' => '王祥求鲤', 'verse' => ['天寒地冻水成冰', '何须贪吝取功名', '只好守己静处坐', '待时兴变自然明'], 'gist' => '冰封之时，静待春融', 'interpretation' => '此签为水结成冰之象。事业时运冻结，贪求功名反受其困，宜守己静待；姻缘冰封未解，缓图为宜；财运不利进取；健康注意寒湿调养。凡事时至冰消、自然明白，此刻静处安居即是上策。'],
    ['no' => 50, 'level' => '中吉', 'title' => '陶朱归五湖', 'verse' => ['五湖四海尽行船', '高挂风帆把舵坚', '幸得顺风随所至', '满船宝贝称心田'], 'gist' => '顺风行船，满载而归', 'interpretation' => '此签为顺风扬帆之象。事业四通八达、一帆风顺，远行经商皆利；姻缘顺水推舟而成；财运大旺，货如轮转；健康心胸开阔则安。凡事把稳舵盘、乘风而进，五湖四海任君行，满载而归可期。'],
    ['no' => 51, 'level' => '上吉', 'title' => '孔明入川', 'verse' => ['夏日初临日正长', '人皆愁恼热非常', '天公也解诸人意', '故遣熏风特送凉'], 'gist' => '天遣凉风，愁中得助', 'interpretation' => '此签为天公送凉之象。事业众人皆愁之际，上天独遣贵人相助，难事迎刃而解；姻缘烦闷之中忽逢知己；财运窘处得援；健康暑热心烦得解。凡事自有天助，不必过虑，熏风一至、烦热顿消。'],
    ['no' => 52, 'level' => '中平', 'title' => '太白醉捞明月', 'verse' => ['水中捉月费工夫', '费尽功夫却又无', '莫信闲言并浪论', '枉抛心力也难图'], 'gist' => '水中捞月，徒劳无功', 'interpretation' => '此签为水中捉月之象。事业所求如镜花水月，费力再多也是空忙，宜及早罢手；姻缘迷恋虚幻，难有结果；财运防画饼之局；健康勿为虚事耗神。凡事莫信闲言浪语，回头是岸，免教心力枉抛。'],
    ['no' => 53, 'level' => '中吉', 'title' => '刘备招亲', 'verse' => ['失意翻成得意时', '龙吟虎啸两相宜', '青云有路终须到', '许我功名必可期'], 'gist' => '失意转得意，青云有路', 'interpretation' => '此签为龙吟虎啸之象。事业先失后得、因祸得福，青云之路虽远终至；姻缘险中成亲，假戏真做亦成佳偶；财运先损后盈；健康转危为安。凡事莫因一时失意而丧志，风云际会，功名必可有期。'],
    ['no' => 54, 'level' => '下下', 'title' => '马超追曹', 'verse' => ['梦中得宝醒来无', '自谓南山只是锄', '若问婚姻并问病', '别寻条路为相扶'], 'gist' => '梦中得宝，醒后成空', 'interpretation' => '此签为梦中得宝之象。事业所谋如梦幻泡影，醒来一无所有，宜别寻出路；姻缘此缘难成，另觅良缘为是；财运空想无益；健康此病此方难愈，宜换医换药。凡事此路不通，及早改弦更张方有转机。'],
    ['no' => 55, 'level' => '中平', 'title' => '周武王登位', 'verse' => ['父贤传子子传孙', '衣禄丰盈只靠天', '金马玉堂人快乐', '饥时吃饭困时眠'], 'gist' => '衣食丰盈，知足常乐', 'interpretation' => '此签为接竹引泉之象。事业守成有余、传承有序，不必好高骛远；姻缘家庭和睦，子孙绵延；财运衣食丰足，靠天安享；健康饥餐困眠、自然康泰。凡事知足常乐，平安即是大福，贪多反失其乐。'],
    ['no' => 56, 'level' => '中平', 'title' => '禄山谋反', 'verse' => ['涧小石粗流水响', '力劳撑驾恐损伤', '路须指出前江去', '风静潮平尽不妨'], 'gist' => '险滩难行，须人指路', 'interpretation' => '此签为船行小滩之象。事业处境艰险、勉强硬撑恐受损伤，须有高人指明前路；姻缘勉强凑合多磨擦；财运不可力取；健康防劳损。凡事虚心求教、循人指点，待风静潮平，自然通行无碍。'],
    ['no' => 57, 'level' => '中吉', 'title' => '董仲寻亲', 'verse' => ['闻是闻非风过耳', '好衣好禄日当空', '君须记取他年事', '汝意还同我意同'], 'gist' => '是非过耳，福禄自丰', 'interpretation' => '此签为是非过耳之象。事业闲言碎语不必挂怀，衣食福禄自有天定、日正当中；姻缘不忘旧情、心意相通终成；财运自有衣禄；健康心宽体健。凡事是是非非付之东风，记取当年情分，终得同心同意。'],
    ['no' => 58, 'level' => '中吉', 'title' => '文王问卜', 'verse' => ['忠言善语君须记', '莫向他方求别艺', '劝君安守旧生涯', '除却有馀都不是'], 'gist' => '忠言须记，安守本业', 'interpretation' => '此签为安守故业之象。事业宜听忠言劝告，守住本行本业，另辟蹊径反而不利；姻缘守旧情、惜眼前人；财运正业可守，旁门莫入；健康安常处顺。凡事除却安守别无他法，忠言逆耳利于行。'],
    ['no' => 59, 'level' => '中平', 'title' => '张良隐山', 'verse' => ['直上高楼去避身', '四边绕绕是荆榛', '谁知造物安排定', '得意翻成失意人'], 'gist' => '高处荆棘，得意防失', 'interpretation' => '此签为高楼荆棘之象。事业避居高位反受围困，得意之时须防转为失意；姻缘强求高处不胜寒；财运见好即收；健康防乐极生悲。凡事造物安排有定，急流勇退、见机而隐，方是全身之道。'],
    ['no' => 60, 'level' => '下下', 'title' => '赤壁鏖兵', 'verse' => ['抱薪救火火增烟', '烧却三千及大千', '若问营谋并出入', '不如收拾莫忧煎'], 'gist' => '抱薪救火，越救越糟', 'interpretation' => '此签为抱薪救火之象。事业方法错误，越补救越乱，当立即停止、收拾残局；姻缘越纠缠越伤情，放手为宜；财运止损为先，切勿加仓硬撑；健康忌病急乱投医。凡事知错即改、知止即智，免得火借薪势、殃及大局。'],
    ['no' => 61, 'level' => '中平', 'title' => '苏小妹难夫', 'verse' => ['日上吟诗月下歌', '逢场作戏笑呵呵', '相逢会遇难藏避', '喝彩齐唱嗹哩啰'], 'gist' => '逢场作戏，随遇而安', 'interpretation' => '此签为逢场作乐之象。事业应酬场面上敷衍周旋即可，不必过分认真；姻缘欢聚有时、聚散随缘；财运小钱可乐，大财莫图；健康心宽自得乐。凡事游戏人间、随遇而安，太过执着反失其趣。'],
    ['no' => 62, 'level' => '中吉', 'title' => '唐僧得道', 'verse' => ['晨昏全赖佛扶持', '虽是逢危不见危', '若得贵人来接引', '此时福禄自相随'], 'gist' => '神佛护佑，逢凶化吉', 'interpretation' => '此签为佛力护持之象。事业虽有惊险实无大碍，贵人接引则福禄相随；姻缘有神明庇佑、善缘终成；财运险中求稳可得；健康逢凶化吉。凡事心存敬畏、多行善念，危难之处自有扶持接引之人。'],
    ['no' => 63, 'level' => '中平', 'title' => '女娲氏炼石', 'verse' => ['昔日行船失了针', '今朝依旧海中寻', '若还寻得原针在', '也费工夫也费心'], 'gist' => '海中寻针，得不偿失', 'interpretation' => '此签为海中寻针之象。事业所寻之物所谋之事费力耗时，纵有所得亦得不偿失，宜权衡取舍；姻缘失而复寻、聚少难圆；财运找回小利却费大工；健康勿为小恙大动干戈。凡事小失不必强求找回，着眼大局为要。'],
    ['no' => 64, 'level' => '下下', 'title' => '马前覆水', 'verse' => ['譬若金鳞放碧漪', '暗遭罗网四边围', '思量无计翻身出', '命到泉关苦独悲'], 'gist' => '鱼落罗网，脱身无计', 'interpretation' => '此签为鱼遭罗网之象。事业身陷重围、四面受制，眼下无计脱身，宜静守待变；姻缘覆水难收，破镜难圆；财运防套牢之困；健康病势缠绵须耐心调治。凡事已入彀中，切勿挣扎硬闯，守静待援或可解脱。'],
    ['no' => 65, 'level' => '中平', 'title' => '孙膑困庞涓', 'verse' => ['眼前欢喜未为欢', '危不危兮安不安', '割肉成疮因甚事', '不如守旧得安全'], 'gist' => '眼前之欢，暗藏危机', 'interpretation' => '此签为割肉成疮之象。事业眼前小利小欢背后藏险，贪之反受其害；姻缘看似甜蜜实多隐患；财运见好莫贪；健康勿以药致病、得不偿失。凡事危安未定之际，守旧最是安全，莫为眼前欢喜误了长远。'],
    ['no' => 66, 'level' => '下下', 'title' => '霸王被困', 'verse' => ['路险马羸人去急', '失群军卒困相当', '滩高风浪船棹破', '日暮花残天降霜'], 'gist' => '四面楚歌，守静无咎', 'interpretation' => '此签为霸王被困之象。事业险阻环生、孤立无援，强行突围必致大败；姻缘离散之象，勿作强求；财运大破之局，收缩保命；健康防急症，宜静养。凡事此时只宜守静守旧、藏锋避祸，妄动则祸上加祸。'],
    ['no' => 67, 'level' => '上吉', 'title' => '金精试窦儿', 'verse' => ['一条金秤等君情', '无增无减无重轻', '为是平生心正直', '文章不识义皆明'], 'gist' => '心平正直，神明可鉴', 'interpretation' => '此签为金秤平心之象。事业凭正直立身，不偏不倚则事事平稳无凶；姻缘真心相待、无欺无诈自成；财运童叟无欺、财源自久；健康心平气和则安。凡事平生心正，鬼神共钦，纵不识文章亦明大义。'],
    ['no' => 68, 'level' => '中吉', 'title' => '郭汾阳祝寿', 'verse' => ['门庭清吉梦祯祥', '积善于门大吉昌', '讼理婚成蚕又熟', '病逢良药得安康'], 'gist' => '积善之家，诸事吉昌', 'interpretation' => '此签为门庭积善之象。事业家宅清吉、祯祥入梦，谋事顺利；姻缘婚事可成；财运蚕熟谷丰、渐入殷实；健康病逢良药、得保安康。凡事皆因积善而来，继续广行善事，福禄自会盈门。'],
    ['no' => 69, 'level' => '中吉', 'title' => '梅开二度', 'verse' => ['冬来岭上一枝梅', '叶落枯枝总不摧', '探得阳春消息近', '依然还我做花魁'], 'gist' => '枯枝不摧，梅开二度', 'interpretation' => '此签为冬岭寒梅之象。事业寒冬虽至而根基不摧，阳春消息已近，复兴在即；姻缘旧情复萌、梅开二度；财运熬过寒冬即回暖；健康冬病春愈。凡事守住骨气耐心等春，花期一至，依旧艳压群芳。'],
    ['no' => 70, 'level' => '下下', 'title' => '李密反唐', 'verse' => ['朝朝役役恰如蜂', '飞来飞去西复东', '春暮花残无觅处', '此身不恋旧丛中'], 'gist' => '劳碌如蜂，春残无获', 'interpretation' => '此签为蜜蜂奔忙之象。事业终日劳碌奔波，春尽花残却一无所获，宜及早改图；姻缘多情反被无情误；财运劳而无得；健康防劳碌成疾。凡事旧丛已无可恋，当断则断、另觅新枝，莫作无益之奔忙。'],
    ['no' => 71, 'level' => '中平', 'title' => '文君访相如', 'verse' => ['谁知爱宠遇强徒', '女子当年嫁二夫', '自是一弓施两箭', '骑龙跨马上安居'], 'gist' => '一弓两箭，终得安居', 'interpretation' => '此签为一弓两箭之象。事业一身二任或两处经营，虽遇强势竞争，终能驾驭得安；姻缘有再嫁二夫之象，几经波折终归安定；财运两路进财；健康起伏后平稳。凡事变故之中自有安排，骑龙跨马、反得安居。'],
    ['no' => 72, 'level' => '中平', 'title' => '王莽求贤', 'verse' => ['弄蜂须要求他蜜', '只怕遭他尾上针', '虽是眼前有异路', '暗里深藏荆棘林'], 'gist' => '刀口舐蜜，利中藏险', 'interpretation' => '此签为弄蜂取蜜之象。事业逐利须防被蜇，眼前虽有别路捷径，暗中荆棘丛生；姻缘甜蜜之下防有刺伤；财运高风险高陷阱，见好即收；健康防蜂虫之伤。凡事利益当前先看风险，贪蜜忘针必受其害。'],
    ['no' => 73, 'level' => '上吉', 'title' => '陈桥兵变', 'verse' => ['春雷震起蛰中虫', '脱却尘凡出旧墉', '忽遇风云交际处', '自然变化得成龙'], 'gist' => '春雷惊蛰，变化成龙', 'interpretation' => '此签为蛰虫化龙之象。事业蛰伏已久，春雷一震脱凡出俗，风云际会之际飞黄腾达；姻缘脱胎换骨、更上层楼；财运突变而发；健康沉疴得脱。凡事时机已然到来，把握风云交会之瞬，一跃成龙。'],
    ['no' => 74, 'level' => '下下', 'title' => '秦败擒三帅', 'verse' => ['慵飞野鹤自投笼', '欲举鹏霄落陷中', '南北东西混障碍', '此身憔悴恨无穷'], 'gist' => '自投罗网，四面受阻', 'interpretation' => '此签为野鹤投笼之象。事业判断失误、自入困境，四方皆阻、动弹不得；姻缘错投非人，悔之晚矣；财运投入即套；健康身心憔悴宜静养。凡事此时不宜轻举妄动，先求脱身止血，日后再图良策。'],
    ['no' => 75, 'level' => '中平', 'title' => '伍员夜出昭关', 'verse' => ['宛如抱虎过山前', '战战兢兢胆碎寒', '幸得山前逢妙手', '方能保得一身安'], 'gist' => '抱虎过山，幸逢援手', 'interpretation' => '此签为抱虎过山之象。事业如临深渊、如履薄冰，惊险万分，幸有高人援手方保平安；姻缘危疑之中得人周全；财运险中求稳；健康虚惊一场。凡事独行难过此关，务必寻求强援，方可保得一身之安。'],
    ['no' => 76, 'level' => '中吉', 'title' => '洪武看牛', 'verse' => ['鱼龙混杂意和同', '耐守寒潭未济中', '不觉一朝头角耸', '禹门一跳到天宫'], 'gist' => '鱼龙未变，一跃登天', 'interpretation' => '此签为鱼龙未变之象。事业眼下混迹平凡、未得施展，耐守寒潭，他日头角一耸、跳禹门而登天；姻缘先贫后贵；财运晚发；健康静待调养。凡事出身寒微不足惧，守得云开，一朝变化便跃天宫。'],
    ['no' => 77, 'level' => '中平', 'title' => '捧璧归赵', 'verse' => ['梦中说梦获多财', '身外浮名总莫猜', '水远山遥难信定', '贵人一指笑颜开'], 'gist' => '浮名如幻，贵人指津', 'interpretation' => '此签为梦中说梦之象。事业虚名浮利不必挂怀，远方消息虚实难定，唯贵人一语点破迷津；姻缘传言不可尽信；财运莫贪虚利；健康勿为虚名劳神。凡事求真务实，得高人一指，迷梦顿醒、笑颜自开。'],
    ['no' => 78, 'level' => '上吉', 'title' => '临潼救驾', 'verse' => ['冷水来浇白雪洋', '不寒不热自温凉', '要行天下无他事', '惟有中藏一艺强'], 'gist' => '一技在身，行遍天下', 'interpretation' => '此签为不温不凉之象。事业身怀一技即可通行天下，深耕专长是立身之本；姻缘性情温和、相处自安；财运凭技艺稳取；健康寒温得调。凡事不必他求，把一门技艺练到精强，自有救驾显能之日。'],
    ['no' => 79, 'level' => '中平', 'title' => '暗扶倒铜旗', 'verse' => ['虚空结愿结人缘', '保得人安愿未还', '得兔忘蹄真绝迹', '敢将初誓谩轻瞒'], 'gist' => '许愿须还，莫忘初心', 'interpretation' => '此签为结愿未还之象。事业曾许之诺须兑现，得人相助莫忘回报，失信则前路渐绝；姻缘立誓当守；财运取之有道、还之有时；健康许还神愿、心诚则安。凡事得兔不可忘蹄，初心一誓不可轻瞒。'],
    ['no' => 80, 'level' => '上吉', 'title' => '智远投军', 'verse' => ['直上高山去学仙', '岂知一旦帝王宣', '青天白日常明照', '志在声名四海传'], 'gist' => '贵人接引，声名远播', 'interpretation' => '此签为贵人接引之象。事业本为清修而去，忽得举荐征召，声名四海传扬；姻缘意外之喜、天作之合；财运不求自得；健康身心明朗。凡事志在青云、行止光明，一朝被召，自可扬名立万。'],
    ['no' => 81, 'level' => '上吉', 'title' => '风送滕王阁', 'verse' => ['庭前叶落暮秋时', '行客奔程势若飞', '谢得天公轻着力', '顺风相送宝船归'], 'gist' => '天公借力，顺风而归', 'interpretation' => '此签为风送归舟之象。事业行程虽急，天公暗中助力，一帆风顺直抵目标；姻缘天助良会；财运宝船满载而归；健康行旅平安。凡事正逢顺风，只管扬帆疾行，天既着力，归程即是获程。'],
    ['no' => 82, 'level' => '中吉', 'title' => '火烧葫芦谷', 'verse' => ['炎炎烈火焰烧天', '焰里还生一朵莲', '到底永成根不坏', '依然枝叶色新鲜'], 'gist' => '火里生莲，历劫不坏', 'interpretation' => '此签为火中生莲之象。事业虽经烈焰考验，根基牢固、似险非险，劫后反更鲜活；姻缘患难见真情；财运经风险而本金无损；健康遇险得安。凡事烈火正是试金之时，根深者不惧，过后枝叶更新。'],
    ['no' => 83, 'level' => '中平', 'title' => '李渊登位', 'verse' => ['譬若初三四五月', '半无半有未圆全', '等待十五良宵夜', '到处光明到处圆'], 'gist' => '月未圆时，静待十五', 'interpretation' => '此签为月初待圆之象。事业目下半缺未满，时机未熟，耐心等待自有圆满之期；姻缘渐趋美满，尚需时日；财运渐渐增益；健康慢慢调养。凡事不必急于一时，待到十五良宵，自然光明遍照、处处团圆。'],
    ['no' => 84, 'level' => '下下', 'title' => '庄子试妻', 'verse' => ['因名丧德不和同', '切忌忙中变作凶', '醉后不知何处去', '青松影里睡蒙眬'], 'gist' => '为名丧德，忙中防凶', 'interpretation' => '此签为醉卧青松之象。事业切勿为虚名而丧德败行，忙乱中最易生变；姻缘试来试去反伤情义；财运不义之财不可取；健康防酒色伤身。凡事守住德行、缓步而行，宁可松下小睡，莫做忙中错事。'],
    ['no' => 85, 'level' => '中平', 'title' => '韩文公遇雪', 'verse' => ['云开雾罩山前路', '万物圆中月再圆', '若得诗书沉梦醒', '贵人指引步天台'], 'gist' => '云开月再圆，贵人引路', 'interpretation' => '此签为云开月圆之象。事业前路曾有云雾遮蔽，守过之后重见光明，得贵人指引更上层楼；姻缘破后重圆；财运失而复得；健康迷梦初醒、渐趋康泰。凡事沉住一口气，诗书医愚、贵人指路，天台可步。'],
    ['no' => 86, 'level' => '上上', 'title' => '商辂中三元', 'verse' => ['春来花发映阳台', '万里舟行进宝来', '跃过禹门三级浪', '恰如平地一声雷'], 'gist' => '连中三元，平地惊雷', 'interpretation' => '此签为平地春雷之象。事业喜事突至、名动四方，跃过龙门三级浪，功名成就惊人；姻缘喜上眉梢；财运万里进宝；健康春回体健。凡事正当时来运转，一声雷响、天下皆知，好生把握此番大运。'],
    ['no' => 87, 'level' => '中平', 'title' => '咬金探地穴', 'verse' => ['人行半岭日衔山', '峻岭巉岩未可攀', '仰望上天垂护佑', '此身犹在太虚间'], 'gist' => '半山遇险，仰仗天佑', 'interpretation' => '此签为半岭衔日之象。事业行至中途、前临险峰不可硬攀，进退两难之际只可静守待援；姻缘悬而未决；财运高不可攀勿强求；健康防高处之险。凡事此时此境，须仰仗天时庇佑，妄进则危、慎守则安。'],
    ['no' => 88, 'level' => '中平', 'title' => '庞洪畏包公', 'verse' => ['木为一虎在当门', '须是有威不害人', '分明说是无防事', '忧恼迟疑恐惊心'], 'gist' => '木虎当门，虚惊一场', 'interpretation' => '此签为木虎有威之象。事业眼中所惧多是虚张声势，实无真害，勿自己吓自己；姻缘疑心生暗鬼；财运怕事反失机；健康多因忧恼而起，宽心即愈。凡事分明无碍，莫让忧恼迟疑乱了心神、误了正事。'],
    ['no' => 89, 'level' => '上吉', 'title' => '智服姜维', 'verse' => ['出入营谋大吉昌', '无瑕玉在石中藏', '如今幸得高人指', '获宝从心喜不胜'], 'gist' => '高人指宝，谋事大吉', 'interpretation' => '此签为石中获宝之象。事业出入营谋皆大吉昌，又得高人指点迷津，如剖石得美玉；姻缘得贵人撮合而成；财运获宝从心、求财得利；健康得遇良医。凡事机缘已到，虚心受教，宝藏在手、喜事不胜。'],
    ['no' => 90, 'level' => '上吉', 'title' => '苇佩遇仙', 'verse' => ['忽朝一信下天墀', '宝贝船装满载归', '若问前程成底事', '始终应得贵人提'], 'gist' => '喜信天降，满载而归', 'interpretation' => '此签为天降喜信之象。事业忽逢佳音，所谋大获成功、满载而归；姻缘天赐良缘；财运宝船满载、进财丰厚；健康喜讯解忧。凡事前程似锦，自始至终多得贵人提携，珍惜机缘、知恩图报。'],
    ['no' => 91, 'level' => '中吉', 'title' => '三战吕布', 'verse' => ['好把愁眉须展开', '大才大用荐将来', '一条大路平如掌', '凡有施为总称怀'], 'gist' => '愁眉展开，大才被荐', 'interpretation' => '此签为前途显达之象。事业忧闷将解，大才终被荐用，此后大路平如掌、施为皆称心；姻缘开朗则缘来；财运通泰；健康愁去身轻。凡事且把愁眉展开，才堪大用、时亦将至，放手作为可也。'],
    ['no' => 92, 'level' => '上吉', 'title' => '蔡卿报恩', 'verse' => ['经商得利称心怀', '福禄荣华倍获财', '若问进身谋望事', '秀才一举状元回'], 'gist' => '经商得利，一举登科', 'interpretation' => '此签为名利双收之象。事业求财得利、求名得名，进身谋望皆有成；姻缘门当户对、锦上添花；财运数倍而还；健康心舒体泰。凡事福禄双全之际，更须记取恩义、回报提携之人，福泽方能长久。'],
    ['no' => 93, 'level' => '中吉', 'title' => '高君保招亲', 'verse' => ['鸾凤翎毛雨压垂', '此时应被雀轻欺', '忽朝一日云霄霁', '依旧还教振羽衣'], 'gist' => '鸾凤暂困，终振羽翼', 'interpretation' => '此签为鸾凤压翎之象。事业一时受困反被小辈轻视，不必介怀，云开雾散之日重振声威；姻缘一时冷落终会转圜；财运暂滞后将通；健康小挫无碍。凡事龙游浅水只是暂时，天霁之后依旧振羽高飞。'],
    ['no' => 94, 'level' => '中平', 'title' => '伯牙访友', 'verse' => ['小人君子别贤愚', '事有差讹惹是非', '琴遇知音当鼓操', '争如定静得便宜'], 'gist' => '琴待知音，静守为利', 'interpretation' => '此签为琴遇知音之象。事业慎辨君子小人，是非易起之时不如定静安守；姻缘知音难觅，宁缺毋滥；财运防因是非破财；健康心静则安。凡事话说与知音、事托与贤者，不是其人，沉默便是便宜。'],
    ['no' => 95, 'level' => '中吉', 'title' => '曹丕称帝', 'verse' => ['事业功勋暮与朝', '荣华物态不胜饶', '报君记取金鸡斗', '福禄声名价自超'], 'gist' => '朝夕勤功，声名自超', 'interpretation' => '此签为朝夕建功之象。事业早晚勤勉经营，荣华富贵渐积渐丰，金鸡一鸣声名鹊起；姻缘用心经营自得美满；财运勤中得财、渐至丰饶；健康规律作息则安。凡事功到自然成，记取时机一唱，身价自超。'],
    ['no' => 96, 'level' => '上上', 'title' => '窦燕山积善', 'verse' => ['巍巍宝塔不寻常', '八面玲珑尽放光', '劝汝志心勤顶礼', '天龙拥护降千祥'], 'gist' => '宝塔放光，积善降祥', 'interpretation' => '此签为宝塔放光之象。事业根基巍峨、前程光明，广积善德则天龙护佑、千祥云集；姻缘善念感天而得佳偶；财运善财滚滚；健康虔心向善、灾病不侵。凡事志心修善、躬行不怠，福祥自会从天而降。'],
    ['no' => 97, 'level' => '中平', 'title' => '六出祁山', 'verse' => ['园林月色摇疏影', '恍若铺成满地琼', '几度儿童来收拾', '岂知收拾总无成'], 'gist' => '月影铺琼，虚景难收', 'interpretation' => '此签为月影似琼之象。事业眼前景象虽美，多为虚影幻景，追逐收拾终无所成，宜辨真伪；姻缘莫被表象迷惑；财运防虚利空欢喜；健康勿为幻影忧思。凡事看破虚华、求其真实，方不至几番收拾总成空。'],
    ['no' => 98, 'level' => '下下', 'title' => '吉平遇难', 'verse' => ['出入求谋事宜迟', '只恐闲愁惹是非', '如鸟飞入罗网里', '相逢能有几多时'], 'gist' => '鸟入罗网，谋事宜迟', 'interpretation' => '此签为鸟投罗网之象。事业出入求谋皆不宜急，急则自投罗网、身陷是非；姻缘相逢苦短、聚时无多；财运动则有险；健康防不测之疾。凡事此时一动不如一静，迟行缓图、远避是非之地，方为自保之道。'],
    ['no' => 99, 'level' => '中平', 'title' => '陶三春挂帅', 'verse' => ['等闲骑马着鞭来', '半有忧危半有财', '似火方烧头上屋', '天教一雨荡殃灾'], 'gist' => '忧危参半，天雨消灾', 'interpretation' => '此签为火屋逢雨之象。事业财利与忧危各半，纵有火烧眉毛之急，自有转机化解；姻缘有惊无险；财运得财须防意外；健康急症得治。凡事祸虽临门，天教时雨一荡殃灾，遇险不必慌，贵人天时皆可恃。'],
    ['no' => 100, 'level' => '下下', 'title' => '三教谈道', 'verse' => ['欲就东兮欲就西', '逢人说事转痴迷', '登山不见神仙面', '莫若归休更勿提'], 'gist' => '东西不定，守旧待时', 'interpretation' => '此签为守常勿动之象。事业心意不定、东西摇摆，逢人诉说反添痴迷，不如归休守旧；姻缘犹豫难决，暂搁为宜；财运不动为安；健康心神宜静。凡事此时求神问卜皆无益，放下执念、静待时来，休要再提。'],
];
